/** Exact 1.39.13 read-only accessors; all Xaero API/types remain inside this optional client adapter. */
public final class Xaero13913Adapter {
 private static Field field(String name,Class<?> type){try{var f=GuiMap.class.getDeclaredField(name);if(type!=null&&f.getType()!=type||!f.trySetAccessible())throw new IllegalStateException("Xaero field unavailable: "+name);return f;}catch(ReflectiveOperationException e){throw new IllegalStateException("Xaero 1.39.13 field missing: "+name,e);}}
 private static final Field CAMERA_X=field("cameraX",double.class),CAMERA_Z=field("cameraZ",double.class),SCALE=field("scale",double.class),VIEWED=field("viewed",null),RIGHT_CLICK=field("rightClickMenu",null),OVER_WAYPOINTS=field("overWaypointsMenu",boolean.class),OVER_PLAYERS=field("overPlayersMenu",boolean.class);
 public static void prepare(){} // Cached accessor validation only; no screen/OpenGL instance is constructed.
 public static void render(GuiMap screen,GuiGraphics g,int mouseX,int mouseY){if(XaeroStatus.failed()||!XaeroStatus.state().supported())return;try{var processor=screen.getMapProcessor();if(processor==null||!processor.isMapWorldUsable()||processor.isRenderingPaused()||processor.getMapWorld()==null){XaeroStatus.waiting("Map world is not ready");return;}var dimension=processor.getMapWorld().getCurrentDimension();if(dimension==null||dimension.getDimId()==null){XaeroStatus.waiting("Viewed dimension unavailable; overlay withheld");return;}var future=screen.getFutureDimension();if(future!=null&&!Objects.equals(future.getDimId(),dimension.getDimId())){XaeroStatus.waiting("Dimension transition; overlay withheld");return;}var mc=Minecraft.getInstance();var window=mc.getWindow();var transform=new MapViewTransform(window.getWidth(),window.getHeight(),window.getGuiScale(),CAMERA_X.getDouble(screen),CAMERA_Z.getDouble(screen),SCALE.getDouble(screen));XaeroStatus.observed();if(!GeographyClientConfig.MAP_ENABLED.get()||!GeographyClient.state().context().participant())return;String dim=dimension.getDimId().location().toString();var map=MapClient.state().snapshot();var view=transform.viewport(screen.width,screen.height);
  if(GeographyClientConfig.MAP_OUTLINES.get()){var visible=map.index().query(dim,MapArea.Kind.LOCAL,view);visible.sort(Comparator.comparingInt(MapArea::priority).thenComparing(MapArea::id));g.enableScissor(0,0,screen.width,screen.height);try{for(var area:visible){var points=area.points();for(int i=0;i<points.size();i++){var a=points.get(i);var b=points.get((i+1)%points.size());var line=transform.segment(a.x(),a.z(),b.x(),b.z(),view);if(line!=null)line(g,line,GeographyClientConfig.MAP_WIDTH.get(),GeographyClientConfig.MAP_OPACITY.get());}}}finally{g.disableScissor();}}
  if(!GeographyClientConfig.MAP_HOVER.get()||RIGHT_CLICK.get(screen)!=null||OVER_WAYPOINTS.getBoolean(screen)||OVER_PLAYERS.getBoolean(screen))return;Object viewed=VIEWED.get(screen);if(viewed instanceof xaero.map.element.HoveredMapElementHolder holder&&holder.getElement()!=null)return;for(var child:screen.children())if(child instanceof AbstractWidget widget&&widget.visible&&widget.isMouseOver(mouseX,mouseY))return;
  double rawX=xaero.map.misc.Misc.getMouseX(mc,false),rawY=xaero.map.misc.Misc.getMouseY(mc,false);var point=transform.world(rawX/window.getGuiScale(),rawY/window.getGuiScale());var hover=map.index().hover(dim,point.x(),point.y());if(hover.visible())tooltip(g,hover,mouseX,mouseY,screen.width,screen.height);
 }catch(RuntimeException|ReflectiveOperationException|LinkageError error){XaeroStatus.disable(error);}}
 private static void line(GuiGraphics g,MapViewTransform.Segment line,double width,double opacity){double dx=line.b().x()-line.a().x(),dy=line.b().y()-line.a().y(),length=Math.hypot(dx,dy);if(length<.01||opacity<=0)return;var pose=g.pose();pose.pushMatrix();try{pose.translate((float)line.a().x(),(float)line.a().y());pose.rotate((float)Math.atan2(dy,dx));pose.scale((float)length,(float)width);int alpha=(int)Math.round(opacity*255);g.fill(0,0,1,1,(alpha<<24)|0xD6E6CE);}finally{pose.popMatrix();}}
 private static String fit(String text,int width,boolean bold){var font=Minecraft.getInstance().font;String value=text;while(!value.isEmpty()){var c=Component.literal(value+(value.equals(text)?"":"..."));if(bold)c.withStyle(ChatFormatting.BOLD);if(font.width(c)<=width)return c.getString();value=value.substring(0,value.offsetByCodePoints(value.length(),-1));}return "";}
 private static void tooltip(GuiGraphics g,MapSpatialIndex.Hover hover,int mouseX,int mouseY,int screenWidth,int screenHeight){var font=Minecraft.getInstance().font;int limit=Math.max(1,Math.min(280,screenWidth-16));String primary=fit(hover.primary(),limit,true),secondary=fit(hover.secondary(),limit,false);var first=Component.literal(primary).withStyle(ChatFormatting.BOLD);int w=Math.max(font.width(first),font.width(secondary))+10,h=secondary.isEmpty()?19:30,x=Math.max(2,Math.min(mouseX+12,screenWidth-w-2)),y=Math.max(2,Math.min(mouseY+12,screenHeight-h-2));g.fill(x,y,x+w,y+h,0xB8000000);g.drawString(font,first,x+5,y+5,0xFFFFFFFF,true);if(!secondary.isEmpty())g.drawString(font,secondary,x+5,y+16,0xFFB8C6D8,true);}
 private Xaero13913Adapter(){}
}
